    "' Controls made while the program runs (D98): New, then Controls.Add puts\n' one on the form, named Button1 and so on unless it was given a Name;\n' AddHandler gives its event a handler; Controls.Remove takes it away.\nDim count As Integer\n\nSub btnAdd_Click()\n    count = count + 1\n    Dim b As New Button\n    b.Caption = \"No. \" & count\n    b.Top = 40 * count\n    b.Tag = CStr(count)\n    If count = 2 Then b.Name = \"btnSecond\"\n    Me.Controls.Add(b)\n    AddHandler b.Click, AddressOf Added_Click\n    Debug.Print(b.Name & \" added: \" & Me.Controls.Count & \" controls\")\nEnd Sub\n\nSub Added_Click(sender As Button)\n    Debug.Print(\"Clicked \" & sender.Name & \" (\" & sender.Tag & \")\")\n    If sender.Tag = \"1\" Then\n        Me.Controls.Remove(sender)\n        sender.Caption = \"gone\"\n        Debug.Print(sender.Name & \" removed, still \" & sender.Caption & \": \" & Me.Controls.Count & \" controls\")\n    End If\nEnd Sub\n",
    [],
    "> btnAdd.Click\nAdd Button1 (Button)\nDebug.Print: Button1 added: 2 controls\n> btnAdd.Click\nAdd btnSecond (Button)\nDebug.Print: btnSecond added: 3 controls\n> btnSecond.Click\nDebug.Print: Clicked btnSecond (2)\n> Button1.Click\nDebug.Print: Clicked Button1 (1)\nRemove Button1\nDebug.Print: Button1 removed, still gone: 2 controls\n> btnAdd.Click\nAdd Button1 (Button)\nDebug.Print: Button1 added: 3 controls\n> Button1.Click\nDebug.Print: Clicked Button1 (3)\n> Close\nClosed\n",
    "formatVersion: 1\nproperties:\n  Height: 400\ncontrols:\n  - { name: btnAdd, type: Button, properties: { Caption: Add } }\n",
    "btnAdd.Click\nbtnAdd.Click\nbtnSecond.Click\nButton1.Click\nbtnAdd.Click   ' Button1 is free again\nButton1.Click\nClose\n",
    null,
