    "dates_format",
    "' Dates and Format (D115): date literals, DateAdd and DateDiff with VB's\n' interval texts and DateInterval, and .NET's format strings for dates\n' and numbers. Fixed dates, so the output is the same every day.\nSub Main()\n    Dim d As Date = #2026-01-31 14:05:09#\n    Debug.Print(Format(d, \"yyyy-MM-dd HH:mm:ss\"))\n    Debug.Print(Format(d, \"dddd, MMMM d, yyyy h:mm tt\"))\n    Debug.Print(Format(DateAdd(\"m\", 1, d), \"yyyy-MM-dd\"))\n    Debug.Print(Format(DateAdd(DateInterval.Year, 2, #2028-02-29#), \"yyyy-MM-dd\"))\n    Debug.Print(Format(DateAdd(\"d\", -1, #2026-03-01#), \"yyyy-MM-dd ddd\"))\n    Debug.Print(DateDiff(\"d\", #2026-01-01#, #2026-12-25#))\n    Debug.Print(DateDiff(DateInterval.Month, #2025-12-31#, #2026-01-01#))\n    Debug.Print(DateDiff(\"yyyy\", #2026-12-31#, #2026-01-01#))\n    Debug.Print(DateDiff(\"ww\", #2026-03-07#, #2026-03-08#))\n    Debug.Print(Format(1234567, \"#,##0\") & \" / \" & Format(1234.5, \"#,##0.00\"))\n    Debug.Print(Format(2.675, \"0.00\") & \" / \" & Format(0.256, \"0.0%\") & \" / \" & Format(7, \"000\"))\n    Debug.Print(Format(-5, \"0;(0)\") & \" / \" & Format(0, \"0;(0);-\") & \" / \" & Format(15000, \"#,##0원\"))\n    ' .NET's standard formats (D118).\n    Debug.Print(Format(d, \"d\") & \" / \" & Format(d, \"D\") & \" / \" & Format(d, \"t\") & \" / \" & Format(d, \"T\") & \" / \" & Format(d, \"%d\"))\n    Debug.Print(Format(1234.567, \"N\") & \" / \" & Format(1234.567, \"N0\") & \" / \" & Format(1234.5, \"F1\") & \" / \" & Format(0.1234, \"P\") & \" / \" & Format(-1234.5, \"C\") & \" / \" & Format(42, \"D5\"))\n    Debug.Print(#2026-10-29# < #2026-10-30#)\n    Debug.Print(DateAdd(\"x\", 1, d))\nEnd Sub\n",
