    "' Anchor (D57): where each control goes when the form changes size.\nSub Show(c As Object)\n    Debug.Print(c.Left & \",\" & c.Top & \" \" & c.Width & \"x\" & c.Height)\nEnd Sub\n\nSub btnShow_Click()\n    Debug.Print(\"Form \" & Me.Width & \"x\" & Me.Height & \" / \" & btnOk.Anchor & \" / [\" & lblMiddle.Anchor & \"]\")\n    Show(btnOk)\n    Show(txtNote)\n    Show(lstAll)\n    Show(lblMiddle)\n    Show(chkLeft)\nEnd Sub\n\nSub btnMove_Click()\n    ' Placed by the program: kept from here on, at this size.\n    lblMiddle.Left = 100\n    chkLeft.Anchor = \"RIGHT top\"\n    ' The program makes the form larger: the controls follow too.\n    Me.Width = 360\nEnd Sub\n",
