    "events_listbox",
    "' ListBox: AddItem, RemoveItem, Clear and List change and read its items;\n' ListCount, ListIndex and Text say what is there and what is chosen.\n' Changed runs whenever ListIndex changes: the user picks an item, the\n' program sets ListIndex, or RemoveItem / Clear moves or removes the\n' chosen item (D46). An item number that does not exist is R003.\nSub Form_Load()\n    lstCity.AddItem(\"Seoul\")\n    lstCity.AddItem(\"Busan\")\n    lstCity.AddItem(\"Daegu\")\n    Debug.Print(lstCity.ListCount & \" items, chosen \" & lstCity.ListIndex & \", text [\" & lstCity.Text & \"]\")\n    Debug.Print(\"item 1: \" & lstCity.List(1))\n    lstCity.ListIndex = 2\n    lstCity.ListIndex = 2\n    Debug.Print(\"same index again: no Changed\")\nEnd Sub\n\nSub lstCity_Changed()\n    Debug.Print(\"Changed: \" & lstCity.ListIndex & \" [\" & lstCity.Text & \"]\")\nEnd Sub\n\nSub btnRemove_Click()\n    lstCity.RemoveItem(0)                  ' before the chosen one: it moves up\n    lstCity.RemoveItem(lstCity.ListIndex)  ' the chosen one: nothing is chosen\n    lstCity.RemoveItem(0)                  ' nothing was chosen: no Changed\n    Debug.Print(lstCity.ListCount & \" items\")\nEnd Sub\n\nSub btnRefill_Click()\n    lstCity.AddItem(\"Incheon\")\n    lstCity.AddItem(\"Gwangju\")\n    lstCity.ListIndex = 1\nEnd Sub\n\nSub btnClear_Click()\n    lstCity.Clear()\n    Debug.Print(\"cleared: \" & lstCity.ListCount & \" items, chosen \" & lstCity.ListIndex)\n    lstCity.Clear                          ' nothing was chosen: no Changed\nEnd Sub\n\nSub btnObject_Click()\n    ' Through an Object variable, the same rules apply.\n    Dim box As Object = lstCity\n    box.RemoveItem(1)\n    box.ListIndex = 0\n    Debug.Print(box.Text & \", \" & box.ListCount)\nEnd Sub\n\nSub btnBad_Click()\n    Debug.Print(lstCity.List(5))\nEnd Sub\n",
    [],
    "Set lstCity.Items: [Seoul]\nSet lstCity.Items: [Seoul, Busan]\nSet lstCity.Items: [Seoul, Busan, Daegu]\nDebug.Print: 3 items, chosen -1, text []\nDebug.Print: item 1: Busan\nSet lstCity.ListIndex: 2\nDebug.Print: Changed: 2 [Daegu]\nSet lstCity.ListIndex: 2\nDebug.Print: same index again: no Changed\n> lstCity.Select 0\nDebug.Print: Changed: 0 [Seoul]\n> lstCity.Select 0\n> lstCity.Select 1\nDebug.Print: Changed: 1 [Busan]\n> btnRemove.Click\nSet lstCity.Items: [Busan, Daegu]\nSet lstCity.ListIndex: 0\nDebug.Print: Changed: 0 [Busan]\nSet lstCity.Items: [Daegu]\nSet lstCity.ListIndex: -1\nDebug.Print: Changed: -1 []\nSet lstCity.Items: []\nDebug.Print: 0 items\n> btnRefill.Click\nSet lstCity.Items: [Incheon]\nSet lstCity.Items: [Incheon, Gwangju]\nSet lstCity.ListIndex: 1\nDebug.Print: Changed: 1 [Gwangju]\n> btnClear.Click\nSet lstCity.Items: []\nSet lstCity.ListIndex: -1\nDebug.Print: Changed: -1 []\nDebug.Print: cleared: 0 items, chosen -1\nSet lstCity.Items: []\n> btnRefill.Click\nSet lstCity.Items: [Incheon]\nSet lstCity.Items: [Incheon, Gwangju]\nSet lstCity.ListIndex: 1\nDebug.Print: Changed: 1 [Gwangju]\n> btnObject.Click\nSet lstCity.Items: [Incheon]\nSet lstCity.ListIndex: -1\nDebug.Print: Changed: -1 []\nSet lstCity.ListIndex: 0\nDebug.Print: Changed: 0 [Incheon]\nDebug.Print: Incheon, 1\n> btnBad.Click\nError R003 @ 49\n",
