    "' A Grid (D116): a CSV file shown, a cell chosen and changed by the user,\n' the total and the average worked out again, a row added and saved.\nSub btnLoad_Click()\n    grdScores.LoadCsv(\"명단.csv\")\n    grdScores.ColumnWidth(0) = 120\n    Debug.Print(grdScores.RowCount & \" rows, \" & grdScores.ColumnCount & \" columns, row \" & grdScores.Row & \", widths \" & grdScores.ColumnWidth(0) & \" \" & grdScores.ColumnWidth(1))\n    ShowTotal()\nEnd Sub\n\nSub ShowTotal()\n    Dim total As Integer = 0\n    For i As Integer = 0 To grdScores.RowCount - 1\n        total = total + CInt(grdScores.Cell(i, \"점수\"))\n    Next\n    lblTotal.Caption = \"합계 \" & total & \", 평균 \" & Format(total / grdScores.RowCount, \"0.0\")\nEnd Sub\n\nSub grdScores_Click()\n    Debug.Print(\"chose \" & grdScores.Row & \",\" & grdScores.Col & \": \" & grdScores.Cell(grdScores.Row, grdScores.Col))\nEnd Sub\n\nSub grdScores_Changed()\n    Debug.Print(\"changed \" & grdScores.Row & \",\" & grdScores.Col & \" to \" & grdScores.Cell(grdScores.Row, grdScores.Col))\n    ShowTotal()\nEnd Sub\n\nSub btnAdd_Click()\n    Dim r As Integer = grdScores.AddRow()\n    grdScores.Cell(r, 0) = \"새 학생\"\n    grdScores.Cell(r, \"점수\") = 0\n    grdScores.Header(1) = \"학급\"\n    grdScores.SaveCsv(\"결과.csv\")\n    ShowTotal()\nEnd Sub\n",
