    "http_json",
    "' Http and JSON (D124, D125, D135): Get, GetJson, Post, PostJson and Send,\n' a header sent with every request, headers for one request, Timeout, and\n' the errors: no answer (R036), a status from 400 (R037), text that is not\n' JSON (R039), a header not written \"Name: value\" (R046).\nSub btnGet_Click()\n    Debug.Print(Http.Timeout)\n    Debug.Print(Http.Get(\"https://api.example.com/hello\"))\n    Http.Header(\"Accept-Language\") = \"ko\"\n    Http.Timeout = 5\n    Debug.Print(Http.Header(\"accept-language\") & \" / \" & Http.Timeout)\n    Debug.Print(Http.Get(\"https://api.example.com/hello\"))\n    Http.Header(\"Accept-Language\") = \"\"\n    Debug.Print(\"[\" & Http.Header(\"Accept-Language\") & \"]\")\nEnd Sub\n\nSub btnJson_Click()\n    Dim scores As Json = Http.GetJson(\"https://api.example.com/scores\")\n    Debug.Print(scores.Kind & \" of \" & scores.Count)\n    For Each s In scores\n        Debug.Print(s(\"name\").AsString & \": \" & s(\"points\").AsInteger & \" (\" & s(\"ok\").AsBoolean & \")\")\n    Next\n    Dim first As Json = scores(0)\n    Debug.Print(first.Text)\n    Debug.Print(first(\"points\").AsDouble / 4)\nEnd Sub\n\nSub btnPost_Click()\n    Debug.Print(Http.Post(\"https://api.example.com/echo\", \"hello\" & vbLf & \"world\"))\n    Dim score As New Json\n    score(\"name\") = \"박둘\"\n    score(\"points\") = 85\n    score(\"tags\") = Json.Array()\n    score(\"tags\").Add(\"quiz\")\n    score(\"tags\").Add(2.5)\n    Dim reply As Json = Http.PostJson(\"https://api.example.com/scores\", score)\n    Debug.Print(reply(\"ok\").AsBoolean & \" #\" & reply(\"id\").AsInteger)\nEnd Sub\n\nSub btnSend_Click()\n    Dim r As HttpResponse = Http.Send(\"get\", \"https://api.example.com/missing\", \"\")\n    Debug.Print(r.Status & \" \" & r.Ok & \" \" & r.Header(\"Content-Type\") & \" \" & r.Text)\n    r = Http.Send(\"POST\", \"https://api.example.com/echo\", \"sent\")\n    Debug.Print(r.Status & \" \" & r.Ok & \" [\" & r.Header(\"X-None\") & \"] \" & r.Text)\n    Debug.Print(Http.Send(\"GET\", \"https://api.example.com/scores\", \"\").Json(1)(\"name\").AsString)\n    ' A secret goes with the one request (D135), over a kept header of its name.\n    Http.Header(\"Accept-Language\") = \"ko\"\n    Dim token As String = \"abc\"\n    r = Http.Send(\"GET\", \"https://api.example.com/hello\", \"\", \"Authorization: Bearer \" & token, \"accept-language: en\")\n    Debug.Print(r.Status & \" \" & r.Text)\n    Debug.Print(Http.Get(\"https://api.example.com/hello\") & \" [\" & Http.Header(\"Authorization\") & \"]\")\n    Http.Header(\"Accept-Language\") = \"\"\n    Try\n        r = Http.Send(\"GET\", \"https://api.example.com/hello\", \"\", \"Authorization\")\n    Catch ex As Exception\n        Debug.Print(ex.Message)\n    End Try\nEnd Sub\n\nSub btnErrors_Click()\n    Try\n        Http.Get(\"https://api.example.com/missing\")\n    Catch ex As Exception\n        Debug.Print(ex.Message)\n    End Try\n    Try\n        Http.GetJson(\"https://api.example.com/hello\")\n    Catch ex As Exception\n        Debug.Print(ex.Message)\n    End Try\n    Try\n        Http.Get(\"https://api.example.com/down\")\n    Catch ex As Exception\n        Debug.Print(ex.Message)\n    End Try\n    Http.Get(\"https://nowhere.example.com/\")\nEnd Sub\n",
    [],
    "> btnGet.Click\nDebug.Print: 30\nHttp: GET https://api.example.com/hello\nDebug.Print: 안녕하세요\nDebug.Print: ko / 5\nHttp: GET https://api.example.com/hello [Accept-Language: ko]\nDebug.Print: 안녕하세요\nDebug.Print: []\n> btnJson.Click\nHttp: GET https://api.example.com/scores [Accept: application/json]\nDebug.Print: Array of 2\nDebug.Print: 김하나: 10 (True)\nDebug.Print: Lee: 7 (False)\nDebug.Print: {\"name\":\"김하나\",\"points\":10,\"ok\":true}\nDebug.Print: 2.5\n> btnPost.Click\nHttp: POST https://api.example.com/echo [Content-Type: text/plain; charset=utf-8] hello\\nworld\nDebug.Print: echoed\nHttp: POST https://api.example.com/scores [Content-Type: application/json; charset=utf-8; Accept: application/json] {\"name\":\"박둘\",\"points\":85,\"tags\":[\"quiz\",2.5]}\nDebug.Print: True #3\n> btnSend.Click\nHttp: GET https://api.example.com/missing\nDebug.Print: 404 False text/html <html>Not here</html>\nHttp: POST https://api.example.com/echo [Content-Type: text/plain; charset=utf-8] sent\nDebug.Print: 201 True [] echoed\nHttp: GET https://api.example.com/scores\nDebug.Print: Lee\nHttp: GET https://api.example.com/hello [Authorization: Bearer abc; accept-language: en]\nDebug.Print: 200 안녕하세요\nHttp: GET https://api.example.com/hello [Accept-Language: ko]\nDebug.Print: 안녕하세요 []\nDebug.Print: A header for Http.Send is written as \"Name: value\"; this one is not: Authorization. Write the name, a colon and the value in one string.\n> btnErrors.Click\nHttp: GET https://api.example.com/missing\nDebug.Print: The server answered 404 to https://api.example.com/missing: <html>Not here</html>. Check the address and what the server expects; Http.Send gives the answer whatever its status.\nHttp: GET https://api.example.com/hello [Accept: application/json]\nDebug.Print: This text is not JSON: unexpected \"안\" at line 1, column 1. Check it at the place named; Http.Get gives the text as it came.\nHttp: GET https://api.example.com/down\nDebug.Print: No answer came from https://api.example.com/down (connection refused). Check the address and the network connection; on the web the server must allow pages from other sites to call it (CORS).\nHttp: GET https://nowhere.example.com/\nError R036 @ 75\n",
