  (
    "keyboard_isdown",
    "' Keyboard.IsDown (D138): which keys are held right now, several at once,\n' asked from a game loop. It knows every key that went down and has not\n' gone up, whether or not Form_KeyDown ran (a TextBox typed in, Shift\n' alone), and every key counts as let go when a dialog opens.\nSub tmrGame_Tick()\n    Dim held As String = \"\"\n    If Keyboard.IsDown(Keys.Left) Then held = held & \"Left \"\n    If Keyboard.IsDown(Keys.Right) Then held = held & \"Right \"\n    If Keyboard.IsDown(Keys.Space) Then held = held & \"Space \"\n    If Keyboard.IsDown(Keys.ShiftKey) Then held = held & \"Shift \"\n    If Keyboard.IsDown(Keys.A) Then held = held & \"A \"\n    Debug.Print(\"Down: \" & held)\nEnd Sub\n\nSub Form_KeyDown(e As KeyEventArgs)\n    Debug.Print(\"KeyDown \" & e.KeyCode)\nEnd Sub\n\nSub btnAsk_Click()\n    MsgBox(\"Every key is let go while this is open\")\nEnd Sub\n",
    [],
    "> tmrGame.Tick\nDebug.Print: Down: \n> Form.KeyDown Left\nDebug.Print: KeyDown 37\n> Form.KeyDown Space\nDebug.Print: KeyDown 32\n> tmrGame.Tick\nDebug.Print: Down: Left Space \n> Form.KeyUp Space\n> Form.KeyDown ShiftKey\n> tmrGame.Tick\nDebug.Print: Down: Left Shift \n> Form.KeyUp ShiftKey\n> Form.KeyUp Left\n> txtName.KeyDown A\n> tmrGame.Tick\nDebug.Print: Down: A \n> txtName.KeyUp A\n> Form.KeyDown Right\nDebug.Print: KeyDown 39\n> btnAsk.Click\nMsgBox: Every key is let go while this is open\n> OK\n> tmrGame.Tick\nDebug.Print: Down: \n> Form.KeyUp Right\n> Close\nClosed\n",
    "formatVersion: 1\ncontrols:\n  - { name: txtName, type: TextBox }\n  - { name: btnAsk, type: Button, properties: { Caption: Ask, Top: 40 } }\n  - { name: tmrGame, type: Timer, properties: { Interval: 16, Enabled: true } }\n",
    "tmrGame.Tick          ' nothing held\nForm.KeyDown Left\nForm.KeyDown Space\ntmrGame.Tick          ' two keys at once\nForm.KeyUp Space\nForm.KeyDown ShiftKey ' Shift alone: no KeyDown, but IsDown knows it\ntmrGame.Tick\nForm.KeyUp ShiftKey\nForm.KeyUp Left\ntxtName.KeyDown A     ' typing in the TextBox: the form gets no KeyDown\ntmrGame.Tick\ntxtName.KeyUp A\nForm.KeyDown Right\nbtnAsk.Click          ' the MsgBox opens: every key is let go\nOK\ntmrGame.Tick          ' Right is not held any more\nForm.KeyUp Right\nClose\n",
