  (
    "keys_move",
    "' The form's keys (D101): KeyDown, again while a key is held, and KeyUp,\n' told the key as e.KeyCode, compared with Keys, and Shift, Control and\n' Alt. Arrow keys move the box, by 10 with Shift; a button with the focus\n' does not take the keys away from the form.\nSub Form_KeyDown(e As KeyEventArgs)\n    Dim stepSize As Integer = 1\n    If e.Shift Then stepSize = 10\n    Select Case e.KeyCode\n        Case Keys.Left\n            lblBox.Left = lblBox.Left - stepSize\n        Case Keys.Right\n            lblBox.Left = lblBox.Left + stepSize\n        Case Keys.Up\n            lblBox.Top = lblBox.Top - stepSize\n        Case Else\n            Debug.Print(\"Key \" & e.KeyCode & \", Control: \" & e.Control & \", Alt: \" & e.Alt)\n    End Select\nEnd Sub\n\nSub Form_KeyUp(e As KeyEventArgs)\n    If e.KeyCode = Keys.Space Then Debug.Print(\"Space let go at \" & lblBox.Left & \", \" & lblBox.Top)\nEnd Sub\n\nSub btnReset_Click()\n    lblBox.Left = 100\n    lblBox.Top = 100\nEnd Sub\n",
