    "milliseconds",
    "' Milliseconds() (D138): the milliseconds since the program started, from\n' a clock that only goes forward. A game loop reads it at the top of each\n' tick and moves by the difference, so that the move does not depend on\n' how often the Timer managed to tick. In a script, Wait moves the clock.\nDim lastTime As Integer\nDim x As Double\n\nSub Form_Load()\n    Debug.Print(\"At start: \" & Milliseconds())\n    lastTime = Milliseconds()\n    tmrGame.Start()\nEnd Sub\n\nSub tmrGame_Tick()\n    Dim dt As Integer = Milliseconds() - lastTime\n    lastTime = Milliseconds()\n    x = x + 30 * dt / 1000       ' 30 pixels a second\n    lblTime.Caption = Milliseconds() & \" ms, x = \" & x\nEnd Sub\n\nSub btnLap_Click()\n    Debug.Print(\"Lap at \" & Milliseconds())\nEnd Sub\n",
    [],
    "Debug.Print: At start: 0\nSet tmrGame.Enabled: True\n> Wait 16\n> tmrGame.Tick\nSet lblTime.Caption: 16 ms, x = 0.48\n> Wait 16\n> tmrGame.Tick\nSet lblTime.Caption: 32 ms, x = 0.96\n> btnLap.Click\nDebug.Print: Lap at 32\n> Wait 500\n> tmrGame.Tick\nSet lblTime.Caption: 532 ms, x = 15.96\n> btnLap.Click\nDebug.Print: Lap at 532\n> Close\nClosed\n",
