  (
    "quiz_best",
    "' 작은 퀴즈: 문제를 보여 주고, ListBox의 보기 가운데 하나를 고르면\n' 맞았는지 알려 주며 점수를 셉니다. 최고 점수는 저장해 두었다가 다음에\n' 실행할 때도 보여 줍니다. 그림 문제는 프로젝트의 그림(pictures 폴더)을\n' Image에 보여 줍니다.\n\n' 문제 하나에 딸린 것을 한 이름으로 묶습니다(Structure).\nStructure Question\n    Text As String\n    Choices(3) As String    ' 보기 네 개\n    Answer As Integer       ' 정답 보기의 번호(0부터)\n    Picture As String       ' 문제의 그림 이름. 그림이 없는 문제는 \"\"\nEnd Structure\n\nDim questions(6) As Question\nDim current As Integer\nDim score As Integer\nDim best As Integer\n\nSub Form_Load()\n    ' New … With { }로 문제 하나를 한 번에 만듭니다. 보기는 { }로 적은 배열입니다.\n    questions(0) = New Question With {.Text = \"대한민국의 수도는 어디일까요?\",\n                                      .Choices = {\"부산\", \"서울\", \"대구\", \"인천\"}, .Answer = 1}\n    questions(1) = New Question With {.Text = \"윤년이 아닌 해는 며칠일까요?\",\n                                      .Choices = {\"360일\", \"365일\", \"366일\", \"370일\"}, .Answer = 1}\n    questions(2) = New Question With {.Text = \"1기압에서 물이 끓는 온도는?\",\n                                      .Choices = {\"50도\", \"80도\", \"100도\", \"120도\"}, .Answer = 2}\n    questions(3) = New Question With {.Text = \"세종대왕이 만든 글자는?\",\n                                      .Choices = {\"한자\", \"한글\", \"가나\", \"알파벳\"}, .Answer = 1}\n    questions(4) = New Question With {.Text = \"7 × 8은 얼마일까요?\",\n                                      .Choices = {\"54\", \"56\", \"58\", \"64\"}, .Answer = 1}\n    questions(5) = New Question With {.Text = \"이 도형의 이름은?\",\n                                      .Choices = {\"사각형\", \"원\", \"삼각형\", \"오각형\"}, .Answer = 2,\n                                      .Picture = \"triangle.png\"}\n    questions(6) = New Question With {.Text = \"이 도형의 꼭짓점은 몇 개일까요?\",\n                                      .Choices = {\"4개\", \"5개\", \"6개\", \"8개\"}, .Answer = 1,\n                                      .Picture = \"pentagon.png\"}\n    ' 지난 실행까지의 최고 점수. 저장된 것이 없으면 \"0\"입니다.\n    best = CInt(GetSetting(\"best\", \"0\"))\n    ShowQuestion(0)\nEnd Sub\n\nSub ShowQuestion(number As Integer)\n    current = number\n    Dim q As Question = questions(number)\n    lblNumber.Caption = \"문제 \" & (number + 1) & \" / \" & (UBound(questions) + 1)\n    lblQuestion.Caption = q.Text\n    ' 그림 이름을 넣으면 그 그림을, \"\"을 넣으면 아무것도 보여 주지 않습니다.\n    imgQuestion.Picture = q.Picture\n    ' Clear()는 고른 항목도 지웁니다. 그래서 고른 것이 있었다면\n    ' lstChoices_Changed가 실행되고, ListIndex는 -1(고른 것 없음)이 됩니다.\n    lstChoices.Clear()\n    For Each choice In q.Choices\n        lstChoices.AddItem(choice)\n    Next\n    lblScore.Caption = \"점수: \" & score & \" · 최고 점수: \" & best\nEnd Sub\n\nSub lstChoices_Changed()\n    ' ListIndex가 바뀔 때마다 실행됩니다: 보기를 고를 때, 그리고 Clear()로\n    ' 고른 것이 없어질 때(ListIndex = -1).\n    If lstChoices.ListIndex = -1 Then\n        btnCheck.Caption = \"정답 확인\"\n    Else\n        btnCheck.Caption = \"확인: \" & lstChoices.Text\n    End If\nEnd Sub\n\nSub btnCheck_Click()\n    If lstChoices.ListIndex = -1 Then\n        MsgBox(\"먼저 보기를 하나 고르세요.\")\n        Exit Sub\n    End If\n    If lstChoices.ListIndex = questions(current).Answer Then\n        score = score + 1\n        MsgBox(\"정답입니다!\")\n    ElseIf chkShowAnswer.Checked Then\n        MsgBox(\"틀렸습니다. 정답: \" & lstChoices.List(questions(current).Answer))\n    Else\n        MsgBox(\"틀렸습니다.\")\n    End If\n    If current < UBound(questions) Then\n        ShowQuestion(current + 1)\n    Else\n        Dim message As String = (UBound(questions) + 1) & \"문제 가운데 \" & score & \"문제를 맞혔습니다.\"\n        If score > best Then\n            ' SaveSetting으로 저장한 값은 프로그램을 다시 실행해도 남습니다.\n            best = score\n            SaveSetting(\"best\", best)\n            message = message & \" 새 최고 점수입니다!\"\n        End If\n        MsgBox(message & \" 처음부터 다시 합니다.\")\n        score = 0\n        ShowQuestion(0)\n    End If\nEnd Sub\n",
    [],
    "Set lblNumber.Caption: 문제 1 / 7\nSet lblQuestion.Caption: 대한민국의 수도는 어디일까요?\nSet imgQuestion.Picture: \nSet lstChoices.Items: []\nSet lstChoices.Items: [부산]\nSet lstChoices.Items: [부산, 서울]\nSet lstChoices.Items: [부산, 서울, 대구]\nSet lstChoices.Items: [부산, 서울, 대구, 인천]\nSet lblScore.Caption: 점수: 0 · 최고 점수: 4\n> btnCheck.Click\nMsgBox: 먼저 보기를 하나 고르세요.\n> OK\n> lstChoices.Select 1\nSet btnCheck.Caption: 확인: 서울\n> btnCheck.Click\nMsgBox: 정답입니다!\n> OK\nSet lblNumber.Caption: 문제 2 / 7\nSet lblQuestion.Caption: 윤년이 아닌 해는 며칠일까요?\nSet imgQuestion.Picture: \nSet lstChoices.Items: []\nSet lstChoices.ListIndex: -1\nSet btnCheck.Caption: 정답 확인\nSet lstChoices.Items: [360일]\nSet lstChoices.Items: [360일, 365일]\nSet lstChoices.Items: [360일, 365일, 366일]\nSet lstChoices.Items: [360일, 365일, 366일, 370일]\nSet lblScore.Caption: 점수: 1 · 최고 점수: 4\n> lstChoices.Select 0\nSet btnCheck.Caption: 확인: 360일\n> btnCheck.Click\nMsgBox: 틀렸습니다.\n> OK\nSet lblNumber.Caption: 문제 3 / 7\nSet lblQuestion.Caption: 1기압에서 물이 끓는 온도는?\nSet imgQuestion.Picture: \nSet lstChoices.Items: []\nSet lstChoices.ListIndex: -1\nSet btnCheck.Caption: 정답 확인\nSet lstChoices.Items: [50도]\nSet lstChoices.Items: [50도, 80도]\nSet lstChoices.Items: [50도, 80도, 100도]\nSet lstChoices.Items: [50도, 80도, 100도, 120도]\nSet lblScore.Caption: 점수: 1 · 최고 점수: 4\n> chkShowAnswer.Click\n> lstChoices.Select 3\nSet btnCheck.Caption: 확인: 120도\n> btnCheck.Click\nMsgBox: 틀렸습니다. 정답: 100도\n> OK\nSet lblNumber.Caption: 문제 4 / 7\nSet lblQuestion.Caption: 세종대왕이 만든 글자는?\nSet imgQuestion.Picture: \nSet lstChoices.Items: []\nSet lstChoices.ListIndex: -1\nSet btnCheck.Caption: 정답 확인\nSet lstChoices.Items: [한자]\nSet lstChoices.Items: [한자, 한글]\nSet lstChoices.Items: [한자, 한글, 가나]\nSet lstChoices.Items: [한자, 한글, 가나, 알파벳]\nSet lblScore.Caption: 점수: 1 · 최고 점수: 4\n> lstChoices.Select 1\nSet btnCheck.Caption: 확인: 한글\n> btnCheck.Click\nMsgBox: 정답입니다!\n> OK\nSet lblNumber.Caption: 문제 5 / 7\nSet lblQuestion.Caption: 7 × 8은 얼마일까요?\nSet imgQuestion.Picture: \nSet lstChoices.Items: []\nSet lstChoices.ListIndex: -1\nSet btnCheck.Caption: 정답 확인\nSet lstChoices.Items: [54]\nSet lstChoices.Items: [54, 56]\nSet lstChoices.Items: [54, 56, 58]\nSet lstChoices.Items: [54, 56, 58, 64]\nSet lblScore.Caption: 점수: 2 · 최고 점수: 4\n> lstChoices.Select 1\nSet btnCheck.Caption: 확인: 56\n> btnCheck.Click\nMsgBox: 정답입니다!\n> OK\nSet lblNumber.Caption: 문제 6 / 7\nSet lblQuestion.Caption: 이 도형의 이름은?\nSet imgQuestion.Picture: triangle.png\nSet lstChoices.Items: []\nSet lstChoices.ListIndex: -1\nSet btnCheck.Caption: 정답 확인\nSet lstChoices.Items: [사각형]\nSet lstChoices.Items: [사각형, 원]\nSet lstChoices.Items: [사각형, 원, 삼각형]\nSet lstChoices.Items: [사각형, 원, 삼각형, 오각형]\nSet lblScore.Caption: 점수: 3 · 최고 점수: 4\n> lstChoices.Select 0\nSet btnCheck.Caption: 확인: 사각형\n> btnCheck.Click\nMsgBox: 틀렸습니다. 정답: 삼각형\n> OK\nSet lblNumber.Caption: 문제 7 / 7\nSet lblQuestion.Caption: 이 도형의 꼭짓점은 몇 개일까요?\nSet imgQuestion.Picture: pentagon.png\nSet lstChoices.Items: []\nSet lstChoices.ListIndex: -1\nSet btnCheck.Caption: 정답 확인\nSet lstChoices.Items: [4개]\nSet lstChoices.Items: [4개, 5개]\nSet lstChoices.Items: [4개, 5개, 6개]\nSet lstChoices.Items: [4개, 5개, 6개, 8개]\nSet lblScore.Caption: 점수: 3 · 최고 점수: 4\n> lstChoices.Select 0\nSet btnCheck.Caption: 확인: 4개\n> btnCheck.Click\nMsgBox: 틀렸습니다. 정답: 5개\n> OK\nMsgBox: 7문제 가운데 3문제를 맞혔습니다. 처음부터 다시 합니다.\n> OK\nSet lblNumber.Caption: 문제 1 / 7\nSet lblQuestion.Caption: 대한민국의 수도는 어디일까요?\nSet imgQuestion.Picture: \nSet lstChoices.Items: []\nSet lstChoices.ListIndex: -1\nSet btnCheck.Caption: 정답 확인\nSet lstChoices.Items: [부산]\nSet lstChoices.Items: [부산, 서울]\nSet lstChoices.Items: [부산, 서울, 대구]\nSet lstChoices.Items: [부산, 서울, 대구, 인천]\nSet lblScore.Caption: 점수: 0 · 최고 점수: 4\n> Close\nClosed\n",
    "formatVersion: 1\nproperties:\n  Caption: 퀴즈\n  Width: 400\n  Height: 300\ncontrols:\n  - name: lblNumber\n    type: Label\n    properties:\n      Left: 16\n      Top: 12\n      Width: 368\n  - name: lblQuestion\n    type: Label\n    properties:\n      Left: 16\n      Top: 40\n      Width: 368\n  - name: lstChoices\n    type: ListBox\n    properties:\n      Left: 16\n      Top: 72\n      Width: 232\n      Height: 116\n  - name: imgQuestion\n    type: Image\n    properties:\n      Left: 264\n      Top: 72\n      Width: 120\n      Height: 116\n  - name: chkShowAnswer\n    type: CheckBox\n    properties:\n      Caption: 틀리면 정답 보여 주기\n      Left: 16\n      Top: 200\n      Width: 240\n  - name: btnCheck\n    type: Button\n    properties:\n      Caption: 정답 확인\n      Left: 16\n      Top: 248\n      Width: 136\n  - name: lblScore\n    type: Label\n    properties:\n      Left: 168\n      Top: 252\n      Width: 216\n",
