    "recursion",
    "' Recursion: every call has its own locals.\nFunction Factorial(n As Integer) As Integer\n    If n <= 1 Then Return 1\n    Return n * Factorial(n - 1)\nEnd Function\n\nFunction Fib(n As Integer) As Integer\n    If n < 2 Then Return n\n    Return Fib(n - 1) + Fib(n - 2)\nEnd Function\n\nSub Main()\n    Debug.Print(Factorial(20))\n    Debug.Print(Fib(20))\n    Try\n        Debug.Print(Factorial(21))\n    Catch\n        Debug.Print(\"21! does not fit\")\n    End Try\nEnd Sub\n",
