    "room_basics",
    "' Room (D136): Create waits until the room is made, then Code, Me and\n' IsHost; Joined, Message and Left as the others come, send and go; Send\n' to everyone, SendTo one member, Lock, Members and NicknameOf; Closed when\n' the room ends. The relay server is the test's, in memory; its codes are\n' pinned.\nSub btnCreate_Click()\n    Debug.Print(\"[\" & rmQuiz.Code & \"] \" & rmQuiz.IsHost)\n    rmQuiz.Create()\n    Debug.Print(rmQuiz.Code & \" \" & rmQuiz.Me & \" \" & rmQuiz.IsHost & \" \" & rmQuiz.Members.Length)\nEnd Sub\n\nSub rmQuiz_Joined(e As RoomEventArgs)\n    Debug.Print(\"joined: \" & e.Nickname & \" (\" & e.Member & \")\")\nEnd Sub\n\nSub rmQuiz_Message(e As RoomEventArgs)\n    Dim answer As Json = e.Json\n    Debug.Print(e.Nickname & \" chose \" & answer(\"choice\").AsInteger)\n    rmQuiz.SendTo(e.Member, \"{\"\"kind\"\":\"\"right\"\"}\")\nEnd Sub\n\nSub rmQuiz_Left(e As RoomEventArgs)\n    Debug.Print(\"left: \" & e.Nickname & \" (\" & e.Member & \")\")\nEnd Sub\n\nSub rmQuiz_Closed(e As RoomEventArgs)\n    Debug.Print(\"closed: \" & e.Reason & \" [\" & rmQuiz.Code & \"]\")\nEnd Sub\n\nSub btnAsk_Click()\n    Dim q As New Json\n    q(\"kind\") = \"question\"\n    q(\"no\") = 1\n    rmQuiz.Send(q.Text)\n    For Each m In rmQuiz.Members\n        Debug.Print(m & \" = \" & rmQuiz.NicknameOf(m))\n    Next\nEnd Sub\n\nSub btnLock_Click()\n    rmQuiz.Lock()\nEnd Sub\n\nSub btnLeave_Click()\n    rmQuiz.Leave()\n    Debug.Print(\"[\" & rmQuiz.Code & \"]\")\n    rmQuiz.Create()\n    Debug.Print(rmQuiz.Code)\nEnd Sub\n",
    [],
    "> btnCreate.Click\nDebug.Print: [] False\nRoom: create\nDebug.Print: K7QPXM m1 True 1\n> Peer 민지 Join\nPeer 민지: entered K7QPXM as m2\nDebug.Print: joined: 민지 (m2)\n> Peer Kim Join\nPeer Kim: entered K7QPXM as m3\nDebug.Print: joined: Kim (m3)\n> btnAsk.Click\nRoom: send {\"kind\":\"question\",\"no\":1}\nPeer 민지 got: {\"kind\":\"question\",\"no\":1}\nPeer Kim got: {\"kind\":\"question\",\"no\":1}\nDebug.Print: m1 = TV\nDebug.Print: m2 = 민지\nDebug.Print: m3 = Kim\n> Peer 민지 Send {\"kind\":\"answer\",\"choice\":2}\nPeer Kim got: {\"kind\":\"answer\",\"choice\":2}\nDebug.Print: 민지 chose 2\nRoom: sendTo m2 {\"kind\":\"right\"}\nPeer 민지 got: {\"kind\":\"right\"}\n> Peer Kim Leave\nDebug.Print: left: Kim (m3)\n> btnLock.Click\nRoom: lock\n> Peer Lee Join\nPeer Lee: error room-locked\n> btnLeave.Click\nRoom: leave\nPeer 민지: closed host left\nDebug.Print: []\nRoom: create\nDebug.Print: ABCDEF\n> Peer Lee Join\nPeer Lee: entered ABCDEF as m2\nDebug.Print: joined: Lee (m2)\n> Room Close idle\nPeer Lee: closed idle\nDebug.Print: closed: idle []\nStill open\nClosed\n",
