    "room_errors",
    "' Room's errors (D136): a room that cannot be entered is R048 with the\n' server's reason (no such room, a locked one), caught by Try; a message\n' over the server's limit comes back as Error; Send while not in a room\n' is R049.\nSub btnJoin_Click()\n    Try\n        rmGame.Join(\"NOROOM\", \"Kim\")\n    Catch ex As Exception\n        Debug.Print(ex.Message)\n    End Try\n    Try\n        rmGame.Join(\"k7q-pxm\", \"Kim\")\n    Catch ex As Exception\n        Debug.Print(ex.Message)\n    End Try\n    rmGame.Join(\"abcdef\", \"Kim\")\n    Debug.Print(rmGame.Code & \" \" & rmGame.Me & \" \" & rmGame.IsHost & \" \" & rmGame.NicknameOf(\"m1\"))\nEnd Sub\n\nSub btnBig_Click()\n    Dim big As String = \"x\"\n    For i As Integer = 1 To 15\n        big = big & big\n    Next\n    rmGame.Send(big)\n    Debug.Print(\"sent\")\nEnd Sub\n\nSub rmGame_Error(e As RoomEventArgs)\n    Debug.Print(\"error: \" & e.Message)\nEnd Sub\n\nSub rmGame_Message(e As RoomEventArgs)\n    Debug.Print(e.Nickname & \": \" & e.Text)\nEnd Sub\n\nSub rmGame_Closed(e As RoomEventArgs)\n    Debug.Print(\"closed: \" & e.Reason)\nEnd Sub\n\nSub btnAlone_Click()\n    rmGame.Send(\"anyone?\")\nEnd Sub\n",
