    "' A lost connection comes back by itself (D136): the program keeps its\n' place in the room (resume), what was sent to it meanwhile comes after,\n' and the others are not told it went.\nSub btnCreate_Click()\n    rmQuiz.Create()\n    Debug.Print(rmQuiz.Code & \" \" & rmQuiz.Me)\nEnd Sub\n\nSub btnSend_Click()\n    rmQuiz.Send(\"question 2\")\nEnd Sub\n\nSub rmQuiz_Message(e As RoomEventArgs)\n    Debug.Print(e.Nickname & \": \" & e.Text)\nEnd Sub\n\nSub rmQuiz_Joined(e As RoomEventArgs)\n    Debug.Print(\"joined: \" & e.Nickname)\nEnd Sub\n\nSub rmQuiz_Left(e As RoomEventArgs)\n    Debug.Print(\"left: \" & e.Nickname)\nEnd Sub\n\nSub rmQuiz_Closed(e As RoomEventArgs)\n    Debug.Print(\"closed: \" & e.Reason)\nEnd Sub\n",
