    "' A Sprite's frames (D138): Frames names the project's pictures, in any\n' case, and reads back with the project's spelling; Frame is the one\n' shown, from 0; with FrameTime above 0, Move turns them, round to the\n' first after the last; new Frames show from the first.\nSub Form_Load()\n    Debug.Print(\"Frames: \" & sprEnemy.Frames & \"; frame \" & sprEnemy.Frame)\n    sprEnemy.Frame = 1\n    Debug.Print(\"Frame \" & sprEnemy.Frame)\n    sprEnemy.FrameTime = 100\n    sprEnemy.Move(50)\n    Debug.Print(\"After 50 ms: frame \" & sprEnemy.Frame)\n    sprEnemy.Move(50)\n    Debug.Print(\"After 100 ms: frame \" & sprEnemy.Frame)\n    sprEnemy.Move(250)\n    Debug.Print(\"After 350 ms: frame \" & sprEnemy.Frame)\n    sprEnemy.Frames = \"BOOM1.PNG, boom2.png\"\n    Debug.Print(\"New frames: \" & sprEnemy.Frames & \"; frame \" & sprEnemy.Frame)\n    sprEnemy.FrameTime = 0\n    sprEnemy.Move(1000)\n    Debug.Print(\"FrameTime 0: frame \" & sprEnemy.Frame)\n    sprEnemy.Frames = \"\"\n    Debug.Print(\"No frames: frame \" & sprEnemy.Frame)\nEnd Sub\n\nSub btnPast_Click()\n    sprEnemy.Frames = \"enemy1.png\"\n    Try\n        sprEnemy.Frame = 1              ' past the last: R051\n    Catch ex As Exception\n        Debug.Print(ex.Message)\n    End Try\n    Debug.Print(\"Still frame \" & sprEnemy.Frame)\nEnd Sub\n\nSub btnUnknown_Click()\n    Try\n        sprEnemy.Frames = \"enemy1.png, nothing.png\"\n    Catch ex As Exception\n        Debug.Print(ex.Message)\n    End Try\n    Debug.Print(\"Still \" & sprEnemy.Frames)\nEnd Sub\n",
