    "' A Sprite's place and speed (D138): X and Y with fractions, Left and Top\n' the same place rounded down, SpeedX and SpeedY in pixels a second, and\n' Move(ms) moving it by them. Nothing moves by itself: the game loop says\n' when, with the milliseconds that passed.\nDim lastTime As Integer\n\nSub Form_Load()\n    Debug.Print(\"At \" & sprShip.X & \", \" & sprShip.Y & \" (\" & sprShip.Left & \", \" & sprShip.Top & \")\")\n    sprShip.X = 10.75\n    Debug.Print(\"X 10.75: Left \" & sprShip.Left & \", X \" & sprShip.X)\n    sprShip.Left = 20\n    Debug.Print(\"Left 20: X \" & sprShip.X)\n    sprShip.SpeedX = 30         ' half a pixel a 16 ms round\n    sprShip.SpeedY = -100\n    lastTime = Milliseconds()\n    tmrGame.Start()\nEnd Sub\n\nSub tmrGame_Tick()\n    Dim dt As Integer = Milliseconds() - lastTime\n    lastTime = Milliseconds()\n    sprShip.Move(dt)\n    Debug.Print(dt & \" ms: X \" & sprShip.X & \", Y \" & sprShip.Y & \" (\" & sprShip.Left & \", \" & sprShip.Top & \")\")\nEnd Sub\n\nSub btnStop_Click()\n    sprShip.SpeedX = 0\n    sprShip.SpeedY = 0\n    sprShip.Move(1000)          ' no speed: it stays\n    Debug.Print(\"Stopped at \" & sprShip.X & \", \" & sprShip.Y)\nEnd Sub\n",
