    "structure_basics",
    "' A Structure keeps related values under one name (D131): fields start\n' at their types' defaults, are read and written by name, and a Structure\n' can hold another. Passed to a procedure, it is copied (ByVal); returned\n' from a function, the caller gets the value.\nStructure Address\n    City As String\n    Zip As Integer\nEnd Structure\n\nStructure Student\n    Name As String\n    Public Score As Integer\n    Dim Born As Date\n    Passed As Boolean\n    Average As Double\n    Home As Address\nEnd Structure\n\nFunction Make(name As String, score As Integer) As Student\n    Dim s As Student\n    s.Name = name\n    s.Score = score\n    s.Passed = score >= 60\n    Return s\nEnd Function\n\nSub Raise(s As Student)\n    s.Score = s.Score + 100\n    Debug.Print(\"inside: \" & s.Score)\nEnd Sub\n\nSub Main()\n    Dim empty As Student\n    Debug.Print(\"[\" & empty.Name & \"] \" & empty.Score & \" \" & empty.Passed & \" \" & empty.Average & \" \" & empty.Born)\n    Dim kim As Student = Make(\"Kim\", 90)\n    kim.Home.City = \"Seoul\"\n    kim.Home.Zip = 4524\n    kim.Average = kim.Score / 4\n    Debug.Print(kim.Name & \" \" & kim.Score & \" \" & kim.Passed & \" \" & kim.Average)\n    Debug.Print(kim.Home.City & \" \" & kim.Home.Zip)\n    Raise(kim)\n    Debug.Print(\"after: \" & kim.Score)\n    Dim made As New Student\n    made.Name = \"Lee\"\n    Debug.Print(made.Name & \" \" & Make(\"Park\", 40).Passed)\nEnd Sub\n",
    [],
    "Debug.Print: [] 0 False 0 0001-01-01 00:00:00\nDebug.Print: Kim 90 True 22.5\nDebug.Print: Seoul 4524\nDebug.Print: inside: 190\nDebug.Print: after: 90\nDebug.Print: Lee False\n",
