  (
    "structure_collections",
    "' Arrays and Lists of a Structure (D131). Each item starts as a new value;\n' Add puts in a copy; a field of an item is changed where the item is,\n' list(0).Score = 1 included (VB.NET does not allow that one). For Each\n' gives each item as a copy. An array field gets its size with ReDim.\nStructure Student\n    Name As String\n    Score As Integer\n    Extra() As Integer\nEnd Structure\n\nSub Main()\n    Dim group(2) As Student\n    group(0).Name = \"Kim\"\n    group(1).Name = \"Lee\"\n    group(1).Score = 70\n    Debug.Print(group(2).Name = \"\" And group(2).Score = 0)\n    ReDim Preserve group(3)\n    Debug.Print(group(1).Name & \" \" & group(1).Score & \" \" & UBound(group))\n\n    Dim list As New List(Of Student)\n    Dim s As Student\n    s.Name = \"Park\"\n    s.Score = 50\n    list.Add(s)\n    s.Score = 99\n    list.Add(s)\n    list(0).Score = list(0).Score + 1\n    Debug.Print(list(0).Score & \" \" & list(1).Score & \" \" & s.Score)\n    list.Insert(0, group(0))\n    list(0).Name = \"Choi\"\n    Debug.Print(list(0).Name & \" \" & group(0).Name & \" \" & list.Count)\n\n    For Each one In list\n        Debug.Print(one.Name & \": \" & one.Score)\n    Next\n    For i = 0 To list.Count - 1\n        list(i).Score = 0\n    Next\n    Debug.Print(list(1).Score + list(2).Score)\n\n    Debug.Print(s.Extra Is Nothing)\n    ReDim s.Extra(2)\n    s.Extra(2) = 3\n    ReDim Preserve s.Extra(4)\n    Debug.Print(s.Extra(2) & \" \" & UBound(s.Extra))\nEnd Sub\n",
