  (
    "structure_copy",
    "' Assigning a Structure copies it whole, its array fields too (D131); a\n' plain array assigned to another variable is the same array, as before.\n' Objects in a Structure (a List) stay the same objects, as an argument's\n' do (LANGUAGE §7.1).\nStructure Card\n    Name As String\n    Marks(2) As Integer\n    Notes As List(Of String)\nEnd Structure\n\nSub Main()\n    Dim a As Card\n    a.Name = \"A\"\n    a.Marks(0) = 1\n    a.Notes = New List(Of String)\n    a.Notes.Add(\"first\")\n\n    Dim b As Card = a\n    b.Name = \"B\"\n    b.Marks(0) = 9\n    b.Notes.Add(\"second\")\n    Debug.Print(a.Name & \" \" & a.Marks(0) & \" \" & a.Notes.Count)\n    Debug.Print(b.Name & \" \" & b.Marks(0) & \" \" & b.Notes.Count)\n\n    ' A plain array: the same array.\n    Dim x(2) As Integer\n    Dim y() As Integer\n    y = x\n    y(0) = 5\n    Debug.Print(\"x(0) = \" & x(0))\n\n    ' An array taken out of a Structure is the Structure's array;\n    ' a copy of the Structure has its own.\n    Dim m() As Integer\n    m = a.Marks\n    m(1) = 7\n    Dim c As Card = a\n    c.Marks(1) = 8\n    Debug.Print(a.Marks(1) & \" \" & c.Marks(1))\n\n    ' Assigned again, the old value is gone.\n    b = a\n    Debug.Print(b.Name & \" \" & b.Marks(0) & \" \" & b.Marks(1))\nEnd Sub\n",
