    "structure_module",
    "' A module's Structure is used in every form, and a form's own Structure\n' in that form (D131). A field of another form's variable is changed\n' where it is kept.\nStructure Pair\n    Left As Student\n    Right As Student\nEnd Structure\n\nDim added As Integer\n\nSub btnAdd_Click()\n    added = added + 1\n    Dim s As Student\n    s.Name = \"No. \" & added\n    s.Score = added * 10\n    Roster.Add(s)\n    Form2.Picked = s\n    Form2.Picked.Score = Form2.Picked.Score + 1\n    Dim p As Pair\n    p.Left = Best()\n    p.Right = Form2.Picked\n    lblBest.Caption = p.Left.Name & \" / \" & p.Right.Name\n    Debug.Print(Roster(added - 1).Score & \" \" & Form2.Picked.Score & \" \" & Form2.Describe())\nEnd Sub\n",
