    "structure_with",
    "' A Structure's value in one expression, New … With (D132), and lists of\n' items for arrays: in a declaration, for an array field, as an argument.\n' Inside braces a line may break without _. The values go in in the order\n' written; a field left out keeps its default.\nStructure Address\n    City As String\nEnd Structure\n\nStructure Question\n    Text As String\n    Choices(3) As String\n    Answer As Integer\n    Home As Address\n    Extra() As Integer\nEnd Structure\n\nDim calls As Integer\n\nFunction Pick(n As Integer) As Integer\n    calls = calls + 1\n    Debug.Print(\"Pick \" & n)\n    Return n\nEnd Function\n\nFunction Total(values() As Integer) As Integer\n    Dim sum As Integer\n    For Each v In values\n        sum = sum + v\n    Next\n    Return sum\nEnd Function\n\nSub Main()\n    Dim q As Question = New Question With {\n        .Text = \"Capital?\",\n        .Answer = Pick(1),\n        .Choices = {\"Busan\", \"Seoul\", \"Daegu\", \"Incheon\"},\n        .Home = New Address With {.City = \"Seoul\"}\n    }\n    Debug.Print(q.Text & \" \" & q.Choices(q.Answer) & \" \" & q.Home.City)\n\n    Dim empty As New Question With {.Text = \"Empty\"}\n    Debug.Print(empty.Text & \" [\" & empty.Choices(0) & \"] \" & empty.Answer & \" \" & (empty.Extra Is Nothing))\n\n    Dim list As New List(Of Question)\n    list.Add(New Question With {.Text = \"Sum\", .Extra = {1, 2, 3}})\n    list.Add(q)\n    Debug.Print(list(0).Text & \" \" & Total(list(0).Extra) & \" \" & list.Count)\n\n    Dim names() As String = {\"Kim\", \"Lee\", \"Park\"}\n    Debug.Print(names(2) & \" \" & UBound(names))\n    Debug.Print(Total({4, 5, 6}) & \" \" & Total({}))\n    Dim mixed = {1, 2.5}\n    Debug.Print(mixed(0) + mixed(1))\n    names = {\"Choi\"}\n    Debug.Print(names(0) & \" \" & UBound(names))\n\n    ' The list is a new array each time it runs.\n    For i = 1 To 2\n        Dim fresh() As Integer = {0, 0}\n        fresh(0) = fresh(0) + i\n        Debug.Print(fresh(0))\n    Next\n    Debug.Print(\"calls: \" & calls)\nEnd Sub\n",
