    "timer_clock",
    "' A Timer (D100): off at first; Start (or Enabled = True) makes it tick\n' every Interval milliseconds, Stop (or Enabled = False) stops it. It is\n' not one of the controls on the form. The script makes each tick.\nDim ticks As Integer\n\nSub Form_Load()\n    Debug.Print(\"Enabled: \" & tmrClock.Enabled & \", every \" & tmrClock.Interval & \" ms; \" & Me.Controls.Count & \" controls\")\nEnd Sub\n\nSub btnStart_Click()\n    tmrClock.Interval = 500\n    tmrClock.Start\n    Debug.Print(\"Started: \" & tmrClock.Enabled & \", every \" & tmrClock.Interval & \" ms\")\nEnd Sub\n\nSub tmrClock_Tick()\n    ticks = ticks + 1\n    lblTime.Caption = ticks & \" ticks\"\n    If ticks = 3 Then tmrClock.Enabled = False\nEnd Sub\n\nSub btnStop_Click()\n    tmrClock.Stop\nEnd Sub\n",
    [],
    "Debug.Print: Enabled: False, every 1000 ms; 3 controls\n> tmrClock.Tick\nDisabled: tmrClock.Tick\n> btnStart.Click\nSet tmrClock.Interval: 500\nSet tmrClock.Enabled: True\nDebug.Print: Started: True, every 500 ms\n> tmrClock.Tick\nSet lblTime.Caption: 1 ticks\n> tmrClock.Tick\nSet lblTime.Caption: 2 ticks\n> tmrClock.Tick\nSet lblTime.Caption: 3 ticks\nSet tmrClock.Enabled: False\n> tmrClock.Tick\nDisabled: tmrClock.Tick\n> btnStart.Click\nSet tmrClock.Interval: 500\nSet tmrClock.Enabled: True\nDebug.Print: Started: True, every 500 ms\n> tmrClock.Tick\nSet lblTime.Caption: 4 ticks\n> btnStop.Click\nSet tmrClock.Enabled: False\n> tmrClock.Tick\nDisabled: tmrClock.Tick\n> Close\nClosed\n",
