  (
    "timer_many",
    "' Several Timers on one form (D100), each at its own Interval: each\n' ticks on its own. While one Tick handler waits (here in DoEvents), the\n' others tick, and its own next tick is ignored; stopping one leaves the\n' others ticking. The script makes each tick, as the clocks would.\nDim fast As Integer\nDim mid As Integer\nDim slow As Integer\nDim waiting As Boolean\n\nSub Show()\n    lblCount.Caption = fast & \" \" & mid & \" \" & slow\nEnd Sub\n\nSub tmrFast_Tick()\n    fast = fast + 1\n    Show()\nEnd Sub\n\nSub tmrMid_Tick()\n    mid = mid + 1\n    Show()\nEnd Sub\n\nSub tmrSlow_Tick()\n    slow = slow + 1\n    Show()\n    Debug.Print(\"slow starts, every \" & tmrSlow.Interval & \" ms\")\n    waiting = True\n    Do While waiting\n        DoEvents\n    Loop\n    Debug.Print(\"slow done: \" & fast & \" \" & mid & \" \" & slow)\nEnd Sub\n\nSub btnGo_Click()\n    waiting = False\nEnd Sub\n\nSub btnStopFast_Click()\n    tmrFast.Stop\nEnd Sub\n",
    [],
    "> tmrFast.Tick\nSet lblCount.Caption: 1 0 0\n> tmrFast.Tick\nSet lblCount.Caption: 2 0 0\n> tmrFast.Tick\nSet lblCount.Caption: 3 0 0\n> tmrMid.Tick\nSet lblCount.Caption: 3 1 0\n> tmrFast.Tick\nSet lblCount.Caption: 4 1 0\n> tmrSlow.Tick\nSet lblCount.Caption: 4 1 1\nDebug.Print: slow starts, every 5000 ms\n> tmrFast.Tick\nSet lblCount.Caption: 5 1 1\n> tmrMid.Tick\nSet lblCount.Caption: 5 2 1\n> tmrSlow.Tick\nIgnored: tmrSlow.Tick\n> btnGo.Click\nDebug.Print: slow done: 5 2 1\n> btnStopFast.Click\nSet tmrFast.Enabled: False\n> tmrFast.Tick\nDisabled: tmrFast.Tick\n> tmrMid.Tick\nSet lblCount.Caption: 5 3 1\n> Close\nClosed\n",
    "formatVersion: 1\ncontrols:\n  - { name: lblCount, type: Label, properties: { Width: 300 } }\n  - { name: btnGo, type: Button, properties: { Caption: Go, Top: 40 } }\n  - { name: btnStopFast, type: Button, properties: { Caption: Stop fast, Top: 40, Left: 120 } }\n  - { name: tmrFast, type: Timer, properties: { Interval: 100, Enabled: true } }\n  - { name: tmrMid, type: Timer, properties: { Interval: 1000, Enabled: true } }\n  - { name: tmrSlow, type: Timer, properties: { Interval: 5000, Enabled: true } }\n",
