    "timer_turns",
    "' A tick is an event like a click (D82, D100): while its handler runs\n' (here waiting in DoEvents) another tick of it is ignored; another\n' Timer's tick runs in the DoEvents; while a MsgBox is open, ticks are\n' blocked.\nDim waiting As Boolean\n\nSub tmrWait_Tick()\n    Debug.Print(\"waiting\")\n    waiting = True\n    Do While waiting\n        DoEvents\n    Loop\n    Debug.Print(\"done waiting\")\nEnd Sub\n\nSub tmrSay_Tick()\n    MsgBox(\"tick\")\nEnd Sub\n\nSub btnGo_Click()\n    waiting = False\nEnd Sub\n",
    [],
    "> tmrWait.Tick\nDebug.Print: waiting\n> tmrWait.Tick\nIgnored: tmrWait.Tick\n> tmrSay.Tick\nMsgBox: tick\n> tmrWait.Tick\nBlocked: tmrWait.Tick\n> OK\n> btnGo.Click\nDebug.Print: done waiting\n> Close\nClosed\n",
    "formatVersion: 1\ncontrols:\n  - { name: btnGo, type: Button, properties: { Caption: Go } }\n  - { name: tmrWait, type: Timer, properties: { Enabled: true } }\n  - { name: tmrSay, type: Timer, properties: { Enabled: true } }\n",
